const body = $input.first().json.body || $input.first().json;
const source = body.source || 'chatgpt';
const title = body.title || 'Untitled';
const content = body.content || '';
const typeHint = body.type_hint || '';

const promptParts = [
  'You are processing captured text for a personal knowledge management system.',
  '\n\nYou classify content using PARA method AND score its actionability (signal quality).',
  '\n\nPARA definitions:',
  '\n- project: has a clear finish line (SaaS app, automation, specific deliverable)',
  '\n- area: ongoing responsibility, no end date (health, finance, business, personal development, ministry)',
  '\n- resource: reference material, research, learning, frameworks, how-to knowledge',
  '\n- inbox: unclear, mixed, needs more context',
  '\n\nSignal Quality: How actionable and valuable is this information?',
  '\nScore 0.0-1.0 based on these factors:',
  '\n✅ Contains specific, actionable next steps (+0.3)',
  '\n✅ Connects to known business area (+0.2)',
  '\n✅ Solves stated problem or removes constraint (+0.2)',
  '\n✅ Contains decision-making criteria (+0.15)',
  '\n✅ New/unique information (not generic) (+0.15)',
  '\n❌ Generic motivation or philosophy (-0.3)',
  '\n❌ Duplicate of existing knowledge (-0.2)',
  '\n❌ Too vague to act on (-0.2)',
  '\n\nContext about the owner:',
  '\n- Builds SaaS apps and business automations',
  '\n- Manages prochattools business (statuslink, xgrow, prochat, says-the-bible, probot)',
  '\n- Has Yeshua Academy (ministry work)',
  '\n- Goal: automate, optimize costs, work efficiently',
  '\n\nExamples:',
  '\n- "Use Stripe for billing" → signal 0.2 (generic)',
  '\n- "Switch to usage-based pricing due to revenue model change" → signal 0.8 (specific, actionable)',
  '\n- "Productivity tips" → signal 0.1 (generic)',
  '\n- "Build n8n webhook to reduce inbox processing from 2h to 5m" → signal 0.9 (specific, measurable)',
  `\n\nTitle hint: ${title}`,
  typeHint ? `\nType hint: ${typeHint}` : '',
  `\n\nContent to analyze:\n${content}`,
  '\n\nRespond ONLY with valid JSON, no markdown:\n{\n  "title": "concise title max 6 words",\n  "para_type": "project|area|resource|inbox",\n  "confidence": 0.0,\n  "signal_quality": 0.0,\n  "area_hint": "which life or business area",\n  "tags": ["tag1"],\n  "summary": "2-3 sentence summary",\n  "key_points": ["point 1"],\n  "action_items": [],\n  "note_content": "markdown body"\n}'
];

const geminiBody = JSON.stringify({
  contents: [{
    parts: [{ text: promptParts.join('') }]
  }]
});

return [{
  json: {
    title,
    content,
    type_hint: typeHint || null,
    source,
    geminiBody
  }
}];

const geminiResponse = $input.first().json;
const inputSource = $('Build Gemini Body').first().json.source || 'chatgpt';
const rawText = geminiResponse.candidates[0].content.parts[0].text;

const stripped = rawText
  .replace(/^```json\s*/m, '')
  .replace(/^```\s*/m, '')
  .replace(/\s*```$/m, '')
  .trim();

function sanitizeJsonString(str) {
  let result = '';
  let inString = false;
  let escaped = false;
  for (let i = 0; i < str.length; i++) {
    const c = str[i];
    if (escaped) {
      result += c;
      escaped = false;
    } else if (c === '\\' && inString) {
      result += c;
      escaped = true;
    } else if (c === '"') {
      result += c;
      inString = !inString;
    } else if (inString && c === '\n') {
      result += '\\n';
    } else if (inString && c === '\r') {
      result += '\\r';
    } else if (inString && c === '\t') {
      result += '\\t';
    } else if (inString && c.charCodeAt(0) < 32) {
      result += '\\u' + c.charCodeAt(0).toString(16).padStart(4, '0');
    } else {
      result += c;
    }
  }
  return result;
}

const cleanJson = sanitizeJsonString(stripped);

let parsed;
try {
  parsed = JSON.parse(cleanJson);
} catch (e) {
  parsed = {
    title: 'Unprocessed capture',
    para_type: 'inbox',
    confidence: 0,
    signal_quality: 0,
    area_hint: '',
    tags: ['needs-review'],
    summary: 'Gemini could not process — review manually.',
    key_points: [],
    action_items: [],
    note_content: rawText
  };
}

let stream = 'review-queue';
if ((parsed.confidence || 0) > 0.8 && (parsed.signal_quality || 0) > 0.7) {
  stream = 'high-value';
} else if ((parsed.confidence || 0) < 0.5 || (parsed.signal_quality || 0) < 0.4) {
  stream = 'junk';
}

const now = new Date();
const date = now.toISOString().slice(0, 10);
const slug = (parsed.title || 'capture')
  .toLowerCase()
  .replace(/[^a-z0-9\s-]/g, '')
  .trim()
  .replace(/\s+/g, '-')
  .slice(0, 40);
const filename = `${date}-${slug}.md`;
const filepath = `notes/inbox/${stream}/${filename}`;

const tagsYaml = (parsed.tags || ['capture'])
  .map(t => `  - ${t}`).join('\n');

const frontmatter = [
  '---',
  'type: capture',
  `source: ${inputSource}`,
  `para_type: ${parsed.para_type || 'inbox'}`,
  `confidence: ${parsed.confidence || 0}`,
  `signal_quality: ${parsed.signal_quality || 0}`,
  `stream: ${stream}`,
  `area: ${parsed.area_hint || ''}`,
  `created: ${date}`,
  'tags:',
  tagsYaml,
  '---'
].join('\n');

const keyPoints = (parsed.key_points || [])
  .map(p => `- ${p}`).join('\n') || '-';
const actionItems = (parsed.action_items || [])
  .map(a => `- [ ] ${a}`).join('\n');
const confPct = Math.round((parsed.confidence || 0) * 100);
const signalPct = Math.round((parsed.signal_quality || 0) * 100);

const noteBody = [
  frontmatter,
  '',
  `# ${parsed.title}`,
  '',
  '## Summary',
  parsed.summary || '',
  '',
  '## Key Points',
  keyPoints,
  '',
  actionItems ? `## Action Items\n${actionItems}\n` : '',
  '## Notes',
  parsed.note_content || '',
  '',
  '---',
  `*Captured · ${date} · ${confPct}% confidence · ${signalPct}% signal · stream: ${stream}*`,
  `*Routed to: notes/inbox/${stream}/*`
].join('\n');

return [{
  json: {
    filepath,
    filename,
    content: noteBody,
    title: parsed.title,
    para_type: parsed.para_type,
    confidence: parsed.confidence,
    signal_quality: parsed.signal_quality,
    stream: stream
  }
}];
